 if(action==='blacksmith'){const entries=[...['weapon','armor'].map(type=>({item:state.equipment[type],target:type})),...state.inventory.map((item,index)=>({item,target:'inventory:'+index}))].filter(e=>e.item?.equipment&&!usableEquipment(e.item));$('blacksmithItems').innerHTML=entries.length?entries.map(({item,target})=>`<article class="equipment-slot">${itemDetailsHTML(item)}<p>${target.startsWith('inventory:')?'In inventory':'Equipped'}</p><button data-repair="${target}">Fix</button></article>`).join(''):'<p>No broken weapons or armor.</p>';$('blacksmithItems').querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>openRepair(b.dataset.repair))}
