function repairItemFor(target){return target?.startsWith('inventory:')?state.inventory[Number(target.slice(10))]:state.equipment[target]}
function openRepair(type){const item=repairItemFor(type);if(!atBlacksmith()||!item?.equipment||usableEquipment(item))return;repairTarget={owner:activeId,type,itemJSON:JSON.stringify(item)};$('repairItemName').textContent=item.name;$('repairCost').value=String(amenity('blacksmith').repairCost);$('repairError').textContent='';$('repairModal').classList.remove('hidden');validateRepairCost();$('repairCost').focus()}
function validRepairTarget(){return repairTarget&&repairTarget.owner===activeId&&atBlacksmith()&&JSON.stringify(repairItemFor(repairTarget.type))===repairTarget.itemJSON}
